(function(){"use strict";function initNavbarScroll(){const navbar=document.querySelector(".navbar");if(!navbar)return;let lastScroll=0;function handleScroll(){const currentScroll=window.scrollY||window.pageYOffset;currentScroll>20?navbar.classList.add("scrolled"):navbar.classList.remove("scrolled");lastScroll=currentScroll}let ticking=!1;window.addEventListener("scroll",function(){if(!ticking){window.requestAnimationFrame(function(){handleScroll();ticking=!1});ticking=!0}},{passive:!0})}function initSmoothScroll(){document.querySelectorAll('a[href^="#"]').forEach(anchor=>{anchor.addEventListener("click",function(e){const href=this.getAttribute("href");if(href==="#"||href==="")return;const target=document.querySelector(href);if(target){e.preventDefault();const offsetTop=target.offsetTop-80;window.scrollTo({top:offsetTop,behavior:"smooth"})}})})}function initLazyLoading(){"loading"in HTMLImageElement.prototype&&(document.querySelectorAll('img[loading="lazy"]').forEach(img=>{img.complete?img.classList.add("loaded"):img.addEventListener("load",function(){this.classList.add("loaded")})}))}function init(){document.readyState==="loading"?document.addEventListener("DOMContentLoaded",function(){initNavbarScroll();initSmoothScroll();initLazyLoading()}):(initNavbarScroll(),initSmoothScroll(),initLazyLoading())}init()})();

